package nl.salah.civicsignal.security;
import static org.assertj.core.api.Assertions.assertThat;import com.fasterxml.jackson.databind.ObjectMapper;import io.micrometer.core.instrument.simple.SimpleMeterRegistry;import java.time.*;import org.junit.jupiter.api.Test;import org.springframework.mock.web.*;
class AdminAuthRateLimitFilterTest{
 @Test void limitsTheEleventhFailedBasicAttempt(){var metrics=new SimpleMeterRegistry();var filter=new AdminAuthRateLimitFilter(Clock.fixed(Instant.parse("2026-01-01T00:00:00Z"),ZoneOffset.UTC),new ObjectMapper(),metrics);for(int i=0;i<11;i++){var req=new MockHttpServletRequest("GET","/api/v1/admin/auth/me");req.addHeader("Authorization","Basic invalid");req.setRemoteAddr("127.0.0.1");var res=new MockHttpServletResponse();try{filter.doFilter(req,res,(a,b)->((jakarta.servlet.http.HttpServletResponse)b).setStatus(401));}catch(Exception e){throw new RuntimeException(e);}if(i==10){assertThat(res.getStatus()).isEqualTo(429);assertThat(res.getHeader("Retry-After")).isNotBlank();}}assertThat(filter.entryCount()).isEqualTo(1);assertThat(metrics.counter("civic_admin_auth_failure_total").count()).isEqualTo(10);assertThat(metrics.counter("civic_admin_rate_limited_total").count()).isEqualTo(1);}
}
